'use strict';
const E=ShiftEngine,$=s=>document.querySelector(s),content=$('#content'),dialog=$('#editor');
let state=E.fresh(),current='2026-10',tab='conditions',undo=[],redo=[],dirty=false;
let requestPerson='',requestKind='E',requestDate='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mo=()=>E.month(state,current),n=()=>E.days(current),k=E.key,chip=c=>E.shifts[c]?.cls||'blank';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function change(fn){undo.push(E.copy(state));if(undo.length>40)undo.shift();redo=[];fn();dirty=true;render();}
function revert(forward){const from=forward?redo:undo,to=forward?undo:redo;if(!from.length)return;to.push(E.copy(state));state=from.pop();dirty=true;render();toast('変更を戻しました');}
function close(){dialog.close();}
function ask(title,text,action){const d=$('#confirm');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="dialog-bottom"><button id="no">戻る</button><button class="primary" id="yes">実行する</button></div>`;d.showModal();$('#no').onclick=()=>d.close();$('#yes').onclick=()=>{d.close();action();};}
function options(vals,selected){return vals.map(([v,l])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('');}
function range(){return Array.from({length:n()},(_,i)=>i+1);}
function headerDays(){return range().map(d=>{const w=E.weekday(current,d);return `<th class="${w===0?'sunday':w===6?'saturday':''}">${d}<small>${'日月火水木金土'[w]}</small></th>`;}).join('');}
function staffRow(p,paid=false){return `<th${paid?' class="paid-person"':''}><span class="person-heading"><span class="person-name">${esc(p.name)}</span>${paid?paidBadge(p):''}</span><span class="person-role">${esc(p.role)}${p.night?' ・夜勤可':''}</span></th>`;}
function undoBar(){return `<button id="undo" ${undo.length?'':'disabled'}>↶ 元に戻す</button><button id="redo" ${redo.length?'':'disabled'}>↷ やり直す</button>`;}
function render(){mo();document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false');});if(tab==='conditions')renderConditions();else if(tab==='schedule')renderSchedule();else renderMembers();if($('#undo'))$('#undo').onclick=()=>revert(false);if($('#redo'))$('#redo').onclick=()=>revert(true);}
function equivalentNote(){return '<div class="equivalent-note"><strong>8時間換算：B・C・D・d・G・Iのみ</strong><span>1人ずつ勤務時間÷8を小数第1位まで切り捨てて合計（8時間＝1.0、6時間＝0.7、7時間＝0.8）。A・E・F・/B・/C・空欄は対象外。</span><span><b class="fte-pass">7.0以上：基準クリア</b> ／ <b class="fte-near">6.0〜6.9：青</b> ／ <b class="fte-low">6.0未満：赤</b></span></div>';}
function equivalentFooter(extra){return '<tfoot><tr class="equivalent-row"><th scope="row">8時間換算 合計<small>B C D d G I</small></th>'+E.dailyEquivalent(state,current).map(r=>'<td class="fte-'+r.status+'" data-equivalent-day="'+r.day+'" aria-label="'+r.day+'日 8時間換算 '+r.value+' '+(r.status==='pass'?'基準クリア':'基準未満')+'" title="'+(r.status==='pass'?'基準クリア':'基準7.0未満')+'">'+r.value+'</td>').join('')+'<td colspan="'+extra+'">—</td></tr></tfoot>';}
function countsPanel(){const rows=E.dailyCounts(state,current),codes=[...Object.keys(E.shifts),'blank'];return '<section class="panel" id="daily-counts"><div class="panel-head"><div><h2>日別・勤務記号別の人数表</h2><p class="desc">各日のA・B・Cなどの人数です。シフトの変更・取り消しに合わせて自動更新します。</p></div></div><div class="grid-wrap"><table class="counts-table" aria-label="日別・勤務記号別の人数表"><thead><tr><th>勤務記号</th>'+headerDays()+'<th>月計（延べ）</th></tr></thead><tbody>'+codes.map(c=>'<tr><th><span class="chip '+chip(c)+'">'+(c==='blank'?'未入力':c+' '+E.shifts[c].label)+'</span></th>'+rows.map(r=>'<td data-count-code="'+c+'" data-count-day="'+r.day+'">'+r.counts[c]+'</td>').join('')+'<td class="count-total">'+rows.reduce((sum,r)=>sum+r.counts[c],0)+'</td></tr>').join('')+'</tbody>'+equivalentFooter(1)+'</table></div>'+equivalentNote()+'<p class="subtle">単位：人。在籍期間内の職員を、記号ごとに1人として集計します。Dとd、Bと/B、Cと/Cは別に数えます。法定配置や時間帯別の人数を判定する表ではありません。</p><p class="subtle">A＝7:00〜16:30（手動入力に対応）。休憩時間が未確認のため、Aを含む勤務時間合計は未確定です。</p></section>';}


const paidLeaveBasis='combined';
function paidBadge(p){const a=E.annualPaidLeave(state,current,p.id,paidLeaveBasis),title=a.start+'〜'+a.end+'／'+a.byMonth.map(r=>r.month+'：'+r.count+'日').join('、');return '<span class="annual-paid-badge" data-paid-person="'+p.id+'" title="'+esc(title)+'">有給 年計 <strong>'+a.total+'</strong> 日</span>';}
function paidYearNote(){const year=Number(current.slice(0,4))-(Number(current.slice(5))<4?1:0);return '<p class="paid-year-note">'+year+'年度（'+year+'年4月〜'+(year+1)+'年3月）｜'+'有給希望「有」とシフトの有休「F」の年間合計（同じ日は1日・予定を含む）。通常のお休み「希／E」は別枠です'+'。未入力月・読み込んでいないデータは含みません。実際の取得実績を確定する機能ではありません。月をまたいで管理するため、終了前に「データを保存」してください。</p>';}

function requestControls(){
 if(requestPerson&&!state.members.some(p=>p.id===requestPerson))requestPerson='';
 return '<form class="request-controls" id="request-form"><label class="field">職員<select id="request-person" required>'+options([['','職員を選択'],...state.members.map(p=>[p.id,p.name])],requestPerson)+'</select></label><label class="field">休みの種類<select id="request-kind">'+options([['E','希望休'],['F','有給']],requestKind)+'</select></label><label class="field">日付<input id="request-date" type="date" required value="'+esc(requestDate)+'"></label><button id="register-request" type="submit" class="primary">登録</button><p class="desc">職員・休みの種類・日付を選んで登録してください。他の月の日付も選べます。登録すると、その月の一覧に切り替わります。</p></form>';
}
function requestAction(value){return value===requestKind?'クリックで解除':requestKind==='F'?'クリックで有給を登録':'クリックで希望休を登録';}
function bindRequestControls(){
 $('#request-person').onchange=e=>{requestPerson=e.target.value;document.querySelectorAll('.request-grid tbody tr').forEach(row=>row.classList.toggle('selected-person',row.dataset.requestRow===requestPerson));};
 $('#request-date').oninput=e=>{requestDate=e.target.value;};
 $('#request-kind').onchange=e=>{const wrap=$('.request-grid')?.closest('.grid-wrap'),left=wrap?.scrollLeft,top=wrap?.scrollTop;requestKind=e.target.value;render();const grid=$('.request-grid')?.closest('.grid-wrap');if(grid){grid.scrollLeft=left;grid.scrollTop=top;}$('#request-kind').focus({preventScroll:true});};
 $('#request-form').onsubmit=e=>{
  e.preventDefault();if(!e.target.reportValidity())return;
  const p=state.members.find(p=>p.id===requestPerson),date=$('#request-date').value,day=Number(date.slice(8)),targetMonth=date.slice(0,7);
  if(!p)return toast('職員を選んでください。');
  if(!/^\d{4}-(0[1-9]|1[0-2])-\d{2}$/.test(date)||Number(date.slice(0,4))<100||!Number.isInteger(day)||day<1||day>E.days(targetMonth))return toast('正しい日付を入力してください。');
  if(!E.active(p,targetMonth,day))return toast('この日は職員の在籍期間外です。日付または在籍期間を確認してください。');
  const id=k(p.id,day),existing=state.months[targetMonth];
  const showTarget=()=>{requestDate=date;current=targetMonth;$('#month').value=current;};
  if(existing?.requests[id]===requestKind){showTarget();render();return toast('同じ内容が登録済みです。');}
  change(()=>{E.month(state,targetMonth).requests[id]=requestKind;showTarget();});
  toast(p.name+' '+date+'の'+(requestKind==='F'?'有給':'希望休')+'を登録しました。'+(mo().generated?'作成済みシフトへの反映は、再作成または手動変更で行ってください。':''));
 };
}
function renderConditions(){const m=mo();
 content.innerHTML=`
 <div class="panel"><div class="panel-head"><h2>全員の希望休一覧</h2><div class="toolbar">${undoBar()}<span class="subtle">職員と日付が交わるセルをクリックして登録・解除</span></div></div>${requestControls()}${paidYearNote()}<div class="legend"><span class="chip off">希 希望休</span><span class="chip paid">有 有給希望</span><span>セルをクリックして${requestKind==='F'?'有給「有」':'希望休「希」'}を入力。同じ種類をもう一度クリックすると解除</span></div><div class="grid-wrap"><table class="request-grid"><thead><tr><th>職員</th>${headerDays()}</tr></thead><tbody>${state.members.map(x=>`<tr data-request-row="${x.id}" class="${requestPerson===x.id?'selected-person':''}">${staffRow(x,true)}${range().map(d=>{const r=m.requests[k(x.id,d)];return `<td><button class="cell ${r?chip(r):'blank'}" data-request-person="${x.id}" data-request-day="${d}" ${E.active(x,current,d)?'':'disabled'} aria-label="${esc(x.name)} ${d}日 ${r==='E'?'希望休':r==='F'?'有給希望':'未登録'}。${requestAction(r)}">${r?(r==='E'?'希':'有'):'＋'}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div>
 <div class="panel"><div class="panel-head"><div><h2>今月の作成条件</h2><p class="desc">配置人数は仮設定です。施設で確認した条件に変更してください。</p></div><button id="generate" class="primary">この条件でシフト案を作る</button></div><div class="fields">${[['B','B 日勤の最低人数'],['C','C 遅番の最低人数'],['D','D 夜勤の最低人数'],['maxRun','連続勤務の上限（日）'],['off','休日の目安（日）']].map(([v,l])=>`<label class="field">${l}<input type="number" required data-rule="${v}" min="${v==='maxRun'?1:0}" max="31" value="${m.rules[v]}"></label>`).join('')}</div><details class="details"><summary>職員ごとの今月の時間・前月末の勤務</summary><p class="subtle">前月の作成データがあれば自動参照します。月末の夜勤・明けは翌月に引き継ぎます。</p><div class="grid-wrap"><table><thead><tr><th>職員</th><th>今月の時間目安（有休込み）</th><th>前月末の勤務</th></tr></thead><tbody>${state.members.map(x=>`<tr>${staffRow(x)}<td><input aria-label="${esc(x.name)} 今月の時間" data-target="${x.id}" type="number" min="0" max="300" required value="${E.target(x,m,n())}"></td><td><select aria-label="${esc(x.name)} 前月末の勤務" data-previous="${x.id}" ${state.months[E.prevMonth(current)]?.generated?'disabled':''}>${options([['','指定なし'],['B','B 日勤'],['C','C 遅番'],['D','D 夜勤入り'],['d','d 夜勤明け'],['E','E 休日'],['F','F 有休']],E.prior(state,current,x))}</select></td></tr>`).join('')}</tbody></table></div></details><details class="details"><summary>日ごとの利用予定・必要人数を変更する</summary><p class="subtle">利用人数は利用者の定例予定から表示します。人数からの法定配置判定は未接続のため、必要人数は担当者が入力します。</p><div class="grid-wrap"><table class="coverage"><thead><tr><th>日付</th><th>通い</th><th>泊まり</th><th>訪問</th><th>B 必要</th><th>C 必要</th><th>D 必要</th></tr></thead><tbody>${range().map(d=>`<tr><th>${d}日（${'日月火水木金土'[E.weekday(current,d)]}）</th>${['通い','泊まり','訪問','B','C','D'].map(v=>`<td><input type="number" min="0" max="100" required aria-label="${d}日 ${v}" data-daily="${d}" data-kind="${v}" value="${m.daily[d]?.[v]??(m.rules[v]??state.users.filter(u=>u.type===v&&E.active(u,current,d)&&u.weekdays.includes(E.weekday(current,d))).length)}"></td>`).join('')}</tr>`).join('')}</tbody></table></div></details></div>`;
 bindRequestControls();
 document.querySelectorAll('[data-request-person]').forEach(b=>b.onclick=()=>{const person=b.dataset.requestPerson,day=+b.dataset.requestDay,id=k(person,day),wrap=b.closest('.grid-wrap'),left=wrap.scrollLeft,top=wrap.scrollTop;change(()=>{const value=m.requests[id];if(value===requestKind)delete m.requests[id];else m.requests[id]=requestKind;});const updated=document.querySelector('[data-request-person="'+person+'"][data-request-day="'+day+'"]'),grid=updated.closest('.grid-wrap');grid.scrollLeft=left;grid.scrollTop=top;updated.focus({preventScroll:true});});
 document.querySelectorAll('[data-rule]').forEach(i=>i.onchange=()=>{if(!i.checkValidity())return i.reportValidity();change(()=>m.rules[i.dataset.rule]=+i.value);});
 document.querySelectorAll('[data-target]').forEach(i=>i.onchange=()=>{if(!i.checkValidity())return i.reportValidity();change(()=>m.targets[i.dataset.target]=+i.value);});
 document.querySelectorAll('[data-previous]').forEach(i=>i.onchange=()=>change(()=>m.previous[i.dataset.previous]=i.value));
 document.querySelectorAll('[data-daily]').forEach(i=>i.onchange=()=>{if(!i.checkValidity())return i.reportValidity();change(()=>{m.daily[i.dataset.daily]??={};m.daily[i.dataset.daily][i.dataset.kind]=+i.value;});});$('#generate').onclick=startGenerate;
}
function startGenerate(){if(mo().conditionPrompt!==undefined&&mo().conditionPrompt!==mo().appliedConditionPrompt){tab='members';render();$('#condition-prompt').focus();toast('変更した条件の反映内容を確認し、「月の作成条件に反映」を押してください。');return;}const conflict=Object.entries(mo().requests).find(([key,c])=>mo().locks[key]&&mo().schedule[key]!==c);if(conflict){const [id,day]=conflict[0].split(':');return toast(`${state.members.find(p=>p.id===id)?.name} ${day}日：希望休と固定勤務が重なっています。先に固定を解除するか、勤務を変更してください。`);}const run=()=>{toast('希望休を確保して、シフトを組んでいます…');const b=$('#generate');if(b){b.disabled=true;b.textContent='作成中…';}setTimeout(()=>{try{change(()=>{E.generate(state,current);tab='schedule';});toast('シフト案を作成しました。要確認の項目を確認してください。');}catch(err){render();toast(err.message);}},60);};if(mo().generated)ask('シフト案を再作成しますか？','希望休と固定したセルを保持して再作成します。固定していない手直しは置き換わります。元に戻すこともできます。',run);else run();}
function scheduleRequestPanel(){return '<section class="panel" id="schedule-request-panel"><h2>希望休・有給を登録</h2>'+requestControls()+'<p class="subtle">希望休一覧と共通の登録内容です。作成済みのシフトは自動変更しません。登録後に再作成するか、勤務セルを手動で変更してください。</p></section>';}
function renderSchedule(){const m=mo();if(!m.generated){content.innerHTML=scheduleRequestPanel()+'<div class="panel empty"><h2>月の条件を入力したら、シフト案を作成</h2><p>希望休を確保し、設定した配置人数を満たす組み合わせを探します。</p><button class="primary" id="generate">シフト案を作る</button> <button id="back-conditions">希望休を入力する</button></div>';$('#generate').onclick=startGenerate;$('#back-conditions').onclick=()=>{tab='conditions';render();};bindRequestControls();return;}
 const issues=E.validate(state,current),bad=new Set(issues.filter(x=>x.id&&x.d).map(x=>k(x.id,x.d))),missing=issues.filter(x=>x.type==='coverage').length;
 content.innerHTML=`${scheduleRequestPanel()}<div class="stats"><div class="stat"><span>登録された希望</span><strong>${Object.keys(m.requests).length}</strong><small> 日分</small></div><div class="stat"><span>固定した勤務</span><strong>${Object.values(m.locks).filter(Boolean).length}</strong><small> セル</small></div><div class="stat warn"><span>人数不足</span><strong>${missing}</strong><small> 項目</small></div><div class="stat warn"><span>その他の要確認</span><strong>${issues.length-missing}</strong><small> 項目</small></div></div><div class="panel"><div class="panel-head"><div><h2>${current.replace('-','年')}月のシフト案</h2><p class="desc">セルをクリックして変更。固定した勤務は再作成しても保持されます。</p></div><div class="toolbar">${undoBar()}<button id="generate">再作成</button><button id="to-counts">日別人数表を見る</button><button id="to-requests">希望休を入力</button><button id="export-csv">CSV出力</button></div></div><div class="legend">${Object.keys(E.shifts).map(c=>`<span class="chip ${chip(c)}">${c} ${E.shifts[c].label}</span>`).join('')}<span>● 固定 ／ 下線 希望あり ／ 赤枠 要確認</span></div><div class="grid-wrap"><table class="schedule-grid"><thead><tr><th>職員</th>${headerDays()}<th>時間 / 目安</th><th>夜勤</th><th>休日</th></tr></thead><tbody>${state.members.map(p=>{const codes=range().map(d=>m.schedule[k(p.id,d)]||''),hours=codes.reduce((v,c)=>v+(E.shifts[c]?.hours||0),0);return `<tr>${staffRow(p,true)}${codes.map((c,i)=>{const d=i+1,id=k(p.id,d);return `<td><button class="cell ${chip(c)} ${m.locks[id]?'locked':''} ${m.requests[id]?'marked':''} ${bad.has(id)?'issue':''} ${!E.active(p,current,d)?'unavailable':''}" data-edit="${p.id}" data-date="${d}" aria-label="${esc(p.name)} ${d}日 ${esc(c||'未入力')}" title="${esc(E.shifts[c]?.label||'未入力')}${m.requests[id]?'・休み希望あり':''}">${c||'—'}</button></td>`;}).join('')}<td>${codes.includes('A')?`${hours}＋A未確定`:hours} / ${E.target(p,m,n())}</td><td>${codes.filter(c=>c==='D').length}</td><td>${codes.filter(c=>c==='E').length}</td></tr>`;}).join('')}${['B','C','D'].map(c=>`<tr class="summary-row"><th>${c} 人数 / 必要</th>${range().map(d=>{const got=state.members.filter(p=>E.active(p,current,d)&&m.schedule[k(p.id,d)]===c).length,need=m.daily[d]?.[c]??m.rules[c];return `<td class="${got<need?'bad':'good'}">${got}/${need}</td>`;}).join('')}<td colspan="3"></td></tr>`).join('')}</tbody>${equivalentFooter(3)}</table></div>${equivalentNote()}<p class="subtle">夜勤はD＋翌日dとして集計します。時間の目安には有休を含みます。</p></div><div class="panel"><div class="panel-head"><h2>確認する項目 ${issues.length}件</h2><span class="subtle">編集すると即時更新します</span></div><div class="issue-list">${issues.map((x,i)=>`<button class="issue-link" data-issue="${i}">${esc(x.text)}</button>`).join('')||'<span>登録した条件に対する警告はありません。</span>'}</div><p class="subtle">チェック対象は画面で設定した条件です。資格別配置、法定基準、月をまたぐ連勤の完全な判定は本番導入時に追加します。</p></div>`;
 bindRequestControls();content.insertAdjacentHTML('beforeend',countsPanel());$('#to-counts').onclick=()=>$('#daily-counts').scrollIntoView({block:'start',behavior:'smooth'});$('#to-requests').onclick=()=>{tab='conditions';render();document.querySelector('.request-grid button:not(:disabled)')?.focus();};
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCell(b.dataset.edit,+b.dataset.date));document.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>{const x=issues[+b.dataset.issue];if(x.id&&x.d)editCell(x.id,x.d);else if(x.d)document.querySelector(`[data-date="${x.d}"]`)?.scrollIntoView({block:'center',inline:'center',behavior:'smooth'});else memberForm(x.id);});$('#generate').onclick=startGenerate;$('#export-csv').onclick=exportCSV;
}
function editCell(id,d){const p=state.members.find(x=>x.id===id),m=mo(),cell=k(id,d),c=m.schedule[cell]||'';dialog.innerHTML=`<div class="dialog-head"><div><span class="subtle">${current.replace('-','年')}月${d}日（${'日月火水木金土'[E.weekday(current,d)]}）</span><h2>${esc(p.name)}</h2></div><button class="close" aria-label="閉じる">×</button></div>${m.requests[cell]?`<div class="note">この日は${m.requests[cell]==='E'?'希望休':'有給希望'}です。変更した場合は要確認として表示します。</div>`:''}<p class="desc">現在：${c?`${c} ${E.shifts[c].label}`:'未入力'}　変更する勤務を選んでください。</p><div class="choices">${Object.entries(E.shifts).map(([v,s])=>`<button class="choice ${s.cls}" data-choice="${v}"><strong>${v} ${s.label}</strong><small>${s.time||'勤務なし'}</small></button>`).join('')}</div><label><input id="lock-edit" type="checkbox" checked> 変更後のセルを固定する</label><p><label><input id="night-set" type="checkbox" checked> Dを選んだとき、翌日d・翌々日Eも設定</label></p><div class="fields"><label class="field">同じ日の勤務を交換する<select id="swap-person"><option value="">交換相手を選択</option>${options(state.members.filter(x=>x.id!==id&&E.active(x,current,d)).map(x=>[x.id,`${x.name}：${m.schedule[k(x.id,d)]||'未入力'}`]),'')}</select></label><button id="swap">勤務を交換</button></div><div class="dialog-bottom"><button id="unlock">${m.locks[cell]?'固定を解除':'現在の勤務を固定'}</button><button id="empty-cell">空欄にする</button><button class="primary close-action">閉じる</button></div>`;dialog.showModal();dialog.querySelector('.close').onclick=close;dialog.querySelector('.close-action').onclick=close;
 dialog.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const v=b.dataset.choice,fix=$('#lock-edit').checked,patches=[[d,v]];if(v==='D'&&$('#night-set').checked){if(d+1<=n())patches.push([d+1,'d']);if(d+2<=n())patches.push([d+2,'E']);}for(const [day,code]of patches){const q=k(id,day);if(day!==d&&((m.locks[q]&&m.schedule[q]!==code)||(m.requests[q]&&m.requests[q]!==code))){toast(`${day}日は固定または希望休があります。先に確認してください。`);return;}}change(()=>{for(const[day,code]of patches){m.schedule[k(id,day)]=code;if(fix)m.locks[k(id,day)]=true;else delete m.locks[k(id,day)];}});close();toast('勤務を変更しました');});
 $('#unlock').onclick=()=>{change(()=>m.locks[cell]?delete m.locks[cell]:m.locks[cell]=true);close();};$('#empty-cell').onclick=()=>{change(()=>{m.schedule[cell]='';m.locks[cell]=true;});close();};$('#swap').onclick=()=>{const other=$('#swap-person').value;if(!other)return toast('交換相手を選んでください');const q=k(other,d);if(m.locks[q])return toast('交換相手の勤務は固定されています。先に解除してください。');change(()=>{[m.schedule[cell],m.schedule[q]]=[m.schedule[q]||'',m.schedule[cell]||''];m.locks[cell]=true;m.locks[q]=true;});close();toast('勤務を交換しました。要確認の項目を確認してください。');};
}

function conditionPanel(){
 const m=mo();if(m.conditionPrompt===undefined){m.conditionPrompt=ShiftConditions.template(m.rules);m.appliedConditionPrompt=m.conditionPrompt;}
 return '<section class="panel condition-panel"><div class="panel-head"><div><h2>シフトを組む条件・プロンプト</h2><p class="desc">'+esc(current)+' の条件です。画像の規則と現在の作成方法を入れています。</p></div><div class="toolbar">'+undoBar()+'</div></div><div class="note">文章は自由に追記できます。自動反映できるのは先頭の5項目のみです。それ以外の文章はメモとして保存し、自動作成の動作は変わりません。</div><label class="field" for="condition-prompt">条件の文章（この月用）</label><textarea id="condition-prompt" maxlength="20000" spellcheck="false" aria-describedby="condition-help">'+esc(m.conditionPrompt)+'</textarea><p id="condition-help" class="subtle">先頭の「項目名：数値＋人／日」の形式を保って編集してください。内容は「データを保存」のファイルにも含まれます。</p><div id="condition-preview" aria-live="polite"></div><div class="toolbar"><button id="apply-condition-prompt" class="primary">月の作成条件に反映</button><button id="condition-to-month">希望休・月の条件を確認</button><button id="condition-copy">前月の文章をコピー</button></div><details class="details"><summary>現在、自動作成で使う設定を確認する</summary><pre class="condition-snapshot">'+esc(conditionSnapshot())+'</pre></details></section>';
}
function conditionSnapshot(){
 const m=mo(),lines=[current+' の現在の有効設定',ShiftConditions.settings(m.rules),'','職員ごとの条件（夜勤可否が優先。職種のみでは制限しません）'];
 for(const p of state.members)lines.push(p.name+'／'+p.role+'／'+(p.night?'夜勤可・月'+p.nightMax+'回まで':'夜勤不可')+'／勤務曜日：'+p.weekdays.map(w=>'日月火水木金土'[w]).join('・')+'／在籍：'+(p.start||'指定なし')+'〜'+(p.end||'指定なし')+'／今月の目安：'+E.target(p,m,n())+'時間／前月末：'+(E.prior(state,current,p)||'未指定'));
 lines.push('','希望休・有給希望');
 for(const p of state.members){const req=range().filter(d=>m.requests[k(p.id,d)]).map(d=>d+'日'+(m.requests[k(p.id,d)]==='E'?'希':'有'));if(req.length)lines.push(p.name+'：'+req.join('、'));}
 lines.push('登録合計：'+Object.keys(m.requests).length+'日分','','固定勤務');
 for(const p of state.members){const fixed=range().filter(d=>m.locks[k(p.id,d)]).map(d=>d+'日'+(m.schedule[k(p.id,d)]||'空欄'));if(fixed.length)lines.push(p.name+'：'+fixed.join('、'));}
 lines.push('','日別の上書き（未指定の日は月の設定・定例利用予定を使用）');
 for(const [day,values]of Object.entries(m.daily))lines.push(day+'日：'+Object.entries(values).map(([c,v])=>c+' '+v+'人').join('、'));
 lines.push('','利用者の定例予定（必要職員数への自動換算なし）');
 for(const u of state.users)lines.push(u.name+'／'+u.type+'／'+u.weekdays.map(w=>'日月火水木金土'[w]).join('・')+'／'+(u.start||'指定なし')+'〜'+(u.end||'指定なし'));
 if(!state.users.length)lines.push('未登録');
 return lines.join('\n');
}
function updateConditionPreview(){
 const m=mo(),parsed=ShiftConditions.parse(m.conditionPrompt),pending=m.conditionPrompt!==m.appliedConditionPrompt;
 $('#condition-preview').innerHTML='<p><strong>'+(pending?'文章を変更済み・まだ反映していません':'反映確認済み')+'</strong></p>'+(parsed.errors.length?'<p class="form-error">'+parsed.errors.map(esc).join('<br>')+'</p>':'<p>反映予定：'+ShiftConditions.fields.map(([key,label])=>esc(label)+' '+m.rules[key]+' → <strong>'+parsed.rules[key]+'</strong>').join(' ／ ')+'</p><p class="subtle">日別の必要人数、個別の勤務時間・勤務曜日・希望休・固定セルは変更しません。本文の参考情報や追加メモは自動適用しません。</p>');
 $('#apply-condition-prompt').disabled=parsed.errors.length>0;
}
function bindConditionPanel(){
 let recorded=false;const input=$('#condition-prompt');
 input.onfocus=()=>{recorded=false;};
 input.oninput=()=>{if(!recorded){undo.push(E.copy(state));if(undo.length>40)undo.shift();redo=[];recorded=true;}mo().conditionPrompt=input.value;dirty=true;updateConditionPreview();$('#undo').disabled=!undo.length;$('#redo').disabled=!redo.length;};
 $('#apply-condition-prompt').onclick=()=>{const parsed=ShiftConditions.parse(mo().conditionPrompt);if(parsed.errors.length)return;change(()=>{Object.assign(mo().rules,parsed.rules);mo().appliedConditionPrompt=mo().conditionPrompt;});toast('先頭の5項目を反映しました。シフトの再作成は別途実行してください。');};
 $('#condition-to-month').onclick=()=>{tab='conditions';render();};
 $('#condition-copy').disabled=typeof state.months[E.prevMonth(current)]?.conditionPrompt!=='string';
 $('#condition-copy').onclick=()=>ask('前月の条件文章をコピーしますか？','この月の文章を置き換えます。設定への反映は、内容を確認してから行ってください。',()=>{change(()=>mo().conditionPrompt=state.months[E.prevMonth(current)].conditionPrompt);});
 updateConditionPreview();
}

function renderMembers(){content.innerHTML=`${conditionPanel()}<div class="two-col"><div class="panel"><div class="panel-head"><h2>職員 ${state.members.length}人</h2><button class="primary" id="add-member">職員を追加</button></div><p class="desc">氏名・夜勤可否・勤務曜日・在籍期間を設定できます。</p><div class="member-list">${state.members.map(p=>`<div class="member-card"><div><p>${esc(p.name)}</p><span class="subtle">${esc(p.role)} / ${p.night?`夜勤 月${p.nightMax}回まで`:'夜勤なし'}<br>${p.start?esc(p.start)+'〜':'開始日指定なし'}${p.end?esc(p.end):''}</span></div><button data-member="${p.id}">編集</button></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h2>利用予定 ${state.users.length}件</h2><button id="add-user">利用者を追加</button></div><p class="desc">利用開始・終了日と、通い・泊まり・訪問の定例予定を登録します。同じ方に複数の予定を追加できます。</p><div class="member-list">${state.users.map(u=>`<div class="member-card"><div><p>${esc(u.name)}</p><span class="subtle">${esc(u.type)} / ${u.weekdays.map(w=>'日月火水木金土'[w]).join('・')}<br>${esc(u.start||'開始日指定なし')}〜${esc(u.end||'')}</span></div><button data-user="${u.id}">編集</button></div>`).join('')||'<p class="empty">定例予定は未登録です。<br>月の条件画面で日別人数を直接入力することもできます。</p>'}</div></div></div><div class="note">現在はサンプル職員です。職員の入れ替えは、新しい職員として追加してください。退職・利用終了は終了日を設定して履歴を残します。</div>`;bindConditionPanel();$('#add-member').onclick=()=>memberForm();$('#add-user').onclick=()=>userForm();document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>memberForm(b.dataset.member));document.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>userForm(b.dataset.user));}
function memberForm(id){editPerson(id,false);}
function userForm(id){editPerson(id,true);}
function editPerson(id,isUser){const list=isUser?state.users:state.members,p=E.copy(list.find(x=>x.id===id)||{id:(isUser?'u':'s')+crypto.randomUUID(),name:'',role:'介護職員',type:'通い',night:false,nightMax:6,target:0,weekdays:[0,1,2,3,4,5,6],start:'',end:''});dialog.innerHTML=`<div class="dialog-head"><h2>${isUser?'利用予定':'職員'}を${id?'変更':'追加'}</h2><button class="close" aria-label="閉じる">×</button></div><form id="person-form"><div class="form-grid"><label class="field full">${isUser?'利用者名または管理番号':'氏名'}<input name="name" required maxlength="50" value="${esc(p.name)}"></label>${isUser?`<label class="field">サービス<select name="type">${options(['通い','泊まり','訪問'].map(x=>[x,x]),p.type)}</select></label><div></div>`:`<label class="field">職種<select name="role">${options(['介護職員','看護職員','管理者','計画作成担当者'].map(x=>[x,x]),p.role)}</select></label><label class="field">夜勤<select name="night">${options([['yes','可能'],['no','不可']],p.night?'yes':'no')}</select></label><label class="field">夜勤の上限（月）<input name="nightMax" type="number" required min="0" max="15" value="${p.nightMax}"></label><label class="field">月の勤務時間目安<input name="target" type="number" required min="0" max="300" value="${p.target}"><small>0＝月の日数と休日目安から算出</small></label>`}<label class="field">${isUser?'利用開始日':'入職日'}<input name="start" type="date" value="${esc(p.start)}"></label><label class="field">${isUser?'利用終了日':'最終勤務日'}<input name="end" type="date" value="${esc(p.end)}"></label><div class="full">${isUser?'利用する':'勤務できる'}曜日<div class="weekday-picks">${[...'日月火水木金土'].map((w,i)=>`<label><input type="checkbox" name="weekdays" value="${i}" ${p.weekdays.includes(i)?'checked':''}>${w}</label>`).join('')}</div></div></div><p id="form-error" class="form-error"></p><div class="dialog-bottom"><button type="button" class="cancel">キャンセル</button><button class="primary" type="submit">保存</button></div></form>`;dialog.showModal();dialog.querySelector('.close').onclick=close;dialog.querySelector('.cancel').onclick=close;$('#person-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('start')&&f.get('end')&&f.get('start')>f.get('end')){$('#form-error').textContent='終了日は開始日以降にしてください。';return;}Object.assign(p,{name:String(f.get('name')).trim(),start:f.get('start'),end:f.get('end'),weekdays:f.getAll('weekdays').map(Number)});if(!p.name){$('#form-error').textContent='氏名を入力してください。';return;}if(isUser)p.type=f.get('type');else Object.assign(p,{role:f.get('role'),night:f.get('night')==='yes',nightMax:+f.get('nightMax'),target:+f.get('target')});change(()=>{if(id)list[list.findIndex(x=>x.id===id)]=p;else list.push(p);});close();toast('保存しました');};}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportCSV(){const safe=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['氏名','職種',...range().map(d=>`${d}日`)],...state.members.map(p=>[p.name,p.role,...range().map(d=>mo().schedule[k(p.id,d)]||'')]),[],['勤務別人数','',...range().map(d=>`${d}日`)],...[...Object.keys(E.shifts),'blank'].map(c=>[c==='blank'?'未入力':c,'人数',...E.dailyCounts(state,current).map(r=>r.counts[c])]),['8時間換算 合計','BCDdGI',...E.dailyEquivalent(state,current).map(r=>r.value)],['換算基準','7.0以上',...E.dailyEquivalent(state,current).map(r=>r.status==='pass'?'基準クリア':r.status==='near'?'6.0台（青）':'6.0未満（赤）')]];download(`あかり_シフト案_${current}.csv`,'\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
$('#month').onchange=e=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){e.target.value=current;return;}current=e.target.value;render();};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});
$('#save').onclick=()=>{download(`あかり_シフトデータ_${current}.json`,JSON.stringify(state,null,2),'application/json');dirty=false;toast('保存ファイルをダウンロードしました');};$('#load').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>5e6)return toast('ファイルが大きすぎます（上限5MB）。');let incoming;try{incoming=E.checkData(JSON.parse(await f.text()));}catch(err){return toast(err.message);}ask('保存データを開きますか？','現在の画面を、ファイルの職員・希望休・シフトで置き換えます。',()=>{change(()=>{state=incoming;});toast('保存データを開きました');});};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!dialog.open&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();revert(e.shiftKey);}});
render();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_shift_requests',title:'希望休を確認',description:'選択中の月の希望休を読み取ります。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({month:current,requests:mo().requests,members:state.members.map(p=>({id:p.id,name:p.name}))})},{name:'set_shift_requests',title:'希望休を登録',description:'指定職員の指定日に希望休または有給希望を登録。シフト自体は変更しません。',inputSchema:{type:'object',properties:{memberId:{type:'string'},days:{type:'array',items:{type:'integer'}},type:{type:'string',enum:['E','F']}},required:['memberId','days','type'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const p=state.members.find(x=>x.id===input.memberId);if(!p||!Array.isArray(input.days)||!input.days.length||!['E','F'].includes(input.type)||input.days.some(d=>!Number.isInteger(d)||d<1||d>n()||!E.active(p,current,d)))throw Error('職員・日付・休みの種類を確認してください。');change(()=>{for(const d of input.days)mo().requests[k(p.id,d)]=input.type;});return {month:current,registered:input.days.length};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
